func main() { os.Exit(run(os.Args[1:], os.Stdout, os.Stderr)) }

func run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("notes", flag.ContinueOnError)
	fs.SetOutput(stderr)
	def := os.Getenv("NOTES_FILE")
	if def == "" {
		def = "notes.txt"
	}
	file := fs.String("file", def, "the notes file")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	usage := func(msg string) int {
		fmt.Fprintf(stderr, "notes: %s\nusage: notes [-file f] add <text> | list | done <n> | clear\n", msg)
		return 2
	}
	if fs.NArg() == 0 {
		return usage("no command")
	}
	notes, err := store.Load(*file)
	if err != nil {
		fmt.Fprintln(stderr, "notes:", err)
		return 1
	}
	rest := fs.Args()[1:]
	switch cmd := fs.Arg(0); cmd {
	case "add":
		text := strings.TrimSpace(strings.Join(rest, " "))
		if text == "" {
			return usage("add needs the note's text")
		}
		notes = append(notes, store.Note{Text: text})
		if err := store.Save(*file, notes); err != nil {
			fmt.Fprintln(stderr, "notes:", err)
			return 1
		}
		fmt.Fprintf(stdout, "added %d: %s\n", len(notes), text)
	case "list":
		if len(notes) == 0 {
			fmt.Fprintln(stdout, "no notes yet")
		}
		for i, n := range notes {
			mark := " "
			if n.Done {
				mark = "x"
			}
			fmt.Fprintf(stdout, "%d [%s] %s\n", i+1, mark, n.Text)
		}
	case "done":
		n, err := strconv.Atoi(strings.Join(rest, ""))
		if err != nil {
			return usage("done needs a note number")
		}
		if err := store.MarkDone(notes, n); err != nil {
			fmt.Fprintln(stderr, "notes:", err)
			return 1
		}
		if err := store.Save(*file, notes); err != nil {
			fmt.Fprintln(stderr, "notes:", err)
			return 1
		}
		fmt.Fprintf(stdout, "done %d: %s\n", n, notes[n-1].Text)
	case "clear":
		var left []store.Note
		for _, n := range notes {
			if !n.Done {
				left = append(left, n)
			}
		}
		cleared := len(notes) - len(left)
		if cleared == 0 {
			fmt.Fprintln(stdout, "nothing to clear")
			return 0
		}
		if err := store.Save(*file, left); err != nil {
			fmt.Fprintln(stderr, "notes:", err)
			return 1
		}
		noun := "notes"
		if cleared == 1 {
			noun = "note"
		}
		fmt.Fprintf(stdout, "cleared %d done %s\n", cleared, noun)
	default:
		return usage(fmt.Sprintf("unknown command %q", cmd))
	}
	return 0
}

package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

// notes runs the CLI on file and returns its exit code and stdout.
func notes(t *testing.T, file string, args ...string) (int, string) {
	t.Helper()
	var out, errOut bytes.Buffer
	code := run(append([]string{"-file", file}, args...), &out, &errOut)
	if errOut.Len() > 0 {
		t.Logf("stderr: %s", errOut.String())
	}
	return code, out.String()
}

// TestClearRemovesDone: criterion 1 of #41. Clearing removes only the done
// note, says how many it removed, and the list renumbers what is left.
func TestClearRemovesDone(t *testing.T) {
	file := filepath.Join(t.TempDir(), "notes.txt")
	for _, n := range []string{"buy milk", "call Ada", "post letter"} {
		notes(t, file, "add", n)
	}
	notes(t, file, "done", "2")
	if code, out := notes(t, file, "clear"); code != 0 || out != "cleared 1 done note\n" {
		t.Fatalf("clear: exit %d, stdout %q", code, out)
	}
	if code, out := notes(t, file, "list"); code != 0 || out != "1 [ ] buy milk\n2 [ ] post letter\n" {
		t.Fatalf("list: exit %d, stdout %q", code, out)
	}
}

// TestClearNothingDone: criterion 2 of #41. With nothing done, clear says so,
// exits 0, and leaves the notes file byte for byte as it was.
func TestClearNothingDone(t *testing.T) {
	file := filepath.Join(t.TempDir(), "notes.txt")
	notes(t, file, "add", "buy milk")
	notes(t, file, "add", "call Ada")
	before, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	if code, out := notes(t, file, "clear"); code != 0 || out != "nothing to clear\n" {
		t.Fatalf("clear: exit %d, stdout %q", code, out)
	}
	after, err := os.ReadFile(file)
	if err != nil || !bytes.Equal(before, after) {
		t.Fatalf("the file changed: %q -> %q (%v)", before, after, err)
	}
}
